using sv_a31b8b17a9d34111b47bb23e8b771696.Models;

namespace sv_a31b8b17a9d34111b47bb23e8b771696.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

using sv_a31b8b17a9d34111b47bb23e8b771696.Models;

namespace sv_a31b8b17a9d34111b47bb23e8b771696.Services;

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> RecipesByCuisine = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Spaghetti Carbonara", "Classic Roman pasta with eggs, pecorino, guanciale, and black pepper.", 30),
            new(2, "Margherita Pizza", "Traditional Neapolitan pizza with tomato, mozzarella, and fresh basil.", 45),
            new(3, "Tiramisu", "Layered coffee-soaked ladyfingers with mascarpone cream and cocoa.", 40),
        },
        [2] = new List<Recipe>
        {
            new(4, "Chicken Tikka Masala", "Tender chicken pieces in a creamy spiced tomato sauce.", 50),
            new(5, "Palak Paneer", "Cottage cheese cubes in a smooth, spiced spinach gravy.", 35),
            new(6, "Biryani", "Fragrant basmati rice layered with marinated meat and aromatic spices.", 90),
        },
        [3] = new List<Recipe>
        {
            new(7, "Tacos al Pastor", "Spit-roasted pork tacos with pineapple, onion, and cilantro.", 60),
            new(8, "Guacamole", "Fresh avocado dip with lime, cilantro, jalapeño, and tomato.", 10),
            new(9, "Churros", "Fried dough pastries coated in cinnamon sugar, served with chocolate sauce.", 25),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        return RecipesByCuisine.TryGetValue(cuisineId, out var recipes)
            ? recipes
            : [];
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@implements IDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation

<PageTitle>Recipes</PageTitle>

<h1>Recipes — Cuisine @CuisineId</h1>

@if (_errorMessage is not null)
{
    <div class="alert alert-danger d-flex justify-content-between align-items-center" role="alert">
        <span>@_errorMessage</span>
        <button class="btn btn-outline-danger btn-sm" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <div class="d-flex align-items-center gap-2 my-4">
        <div class="spinner-border text-primary" role="status"></div>
        <span>Loading recipes…</span>
    </div>
}
else
{
    if (_isRefreshing)
    {
        <div class="alert alert-info py-1 px-3 d-inline-flex align-items-center gap-2" role="status">
            <div class="spinner-border spinner-border-sm"></div>
            <span>Refreshing…</span>
        </div>
    }

    <div class="mb-3">
        <label class="form-label fw-bold">Sort by:</label>
        <a href="@GetSortUrl("newest")" class="btn btn-sm @(CurrentSort == "newest" ? "btn-primary" : "btn-outline-primary")">Newest</a>
        <a href="@GetSortUrl("popular")" class="btn btn-sm @(CurrentSort == "popular" ? "btn-primary" : "btn-outline-primary")">Popular</a>
    </div>

    @if (_recipes.Count == 0)
    {
        <p class="text-muted">No recipes found for this cuisine.</p>
    }
    else
    {
        <div class="row row-cols-1 row-cols-md-3 g-3">
            @foreach (var recipe in GetSortedRecipes())
            {
                <div class="col">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text">@recipe.Description</p>
                        </div>
                        <div class="card-footer text-muted">
                            Prep time: @recipe.PrepTimeMinutes min
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

@code {
    private CancellationTokenSource? _cts;
    private List<Recipe>? _recipes;
    private bool _isRefreshing;
    private string? _errorMessage;
    private int _loadedCuisineId;

    private string CurrentSort => Sort?.ToLowerInvariant() switch
    {
        "popular" => "popular",
        _ => "newest",
    };

    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    public override async Task SetParametersAsync(ParameterView parameters)
    {
        var previousCuisineId = CuisineId;
        await base.SetParametersAsync(parameters);

        if (CuisineId != previousCuisineId || (_recipes is null && _errorMessage is null))
        {
            await LoadRecipesAsync();
        }
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight request.
        await CancelPendingRequestAsync();

        _errorMessage = null;
        _isRefreshing = _recipes is not null;
        _loadedCuisineId = CuisineId;
        StateHasChanged();

        var cts = new CancellationTokenSource();
        _cts = cts;

        try
        {
            var results = await RecipeService.GetByCuisineAsync(CuisineId, cts.Token);

            // Guard against a stale response arriving after a newer request was started.
            if (cts.Token.IsCancellationRequested)
            {
                return;
            }

            _recipes = results;
            _isRefreshing = false;
            _errorMessage = null;
        }
        catch (OperationCanceledException) when (cts.Token.IsCancellationRequested)
        {
            // Expected when the user navigates to a different cuisine or leaves the page.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _isRefreshing = false;
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _isRefreshing = false;
            _errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
    }

    private async Task RetryAsync()
    {
        await LoadRecipesAsync();
    }

    private IEnumerable<Recipe> GetSortedRecipes()
    {
        if (_recipes is null) return [];

        return CurrentSort switch
        {
            "popular" => _recipes.OrderBy(r => r.PrepTimeMinutes),
            _ => _recipes.OrderByDescending(r => r.Id),
        };
    }

    private string GetSortUrl(string sort) =>
        Navigation.GetUriWithQueryParameter("sort", sort);

    private async Task CancelPendingRequestAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }
}

