    private static readonly Dictionary<int, List<Recipe>> RecipesByCuisine = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Spaghetti Carbonara", "Classic Roman pasta with eggs, pecorino, guanciale, and black pepper.", 30),
            new(2, "Margherita Pizza", "Traditional Neapolitan pizza with tomato, mozzarella, and fresh basil.", 45),
            new(3, "Tiramisu", "Layered coffee-soaked ladyfingers with mascarpone cream and cocoa.", 40),
        },
        [2] = new List<Recipe>
        {
            new(4, "Chicken Tikka Masala", "Tender chicken pieces in a creamy spiced tomato sauce.", 50),
            new(5, "Palak Paneer", "Cottage cheese cubes in a smooth, spiced spinach gravy.", 35),
            new(6, "Biryani", "Fragrant basmati rice layered with marinated meat and aromatic spices.", 90),
        },
        [3] = new List<Recipe>
        {
            new(7, "Tacos al Pastor", "Spit-roasted pork tacos with pineapple, onion, and cilantro.", 60),
            new(8, "Guacamole", "Fresh avocado dip with lime, cilantro, jalapeño, and tomato.", 10),
            new(9, "Churros", "Fried dough pastries coated in cinnamon sugar, served with chocolate sauce.", 25),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
